"""Generate a list or list of lists containing a single value.

    Parameters
    ----------
    val_for_list : any
        Value that will be repeated in list or lists of lists.
    list_len : int
        Length of list output, or lists within list if multiple.
    num_lists : int, optional
        If > 1, number of lists within list of lists output. The default is 1.

    Returns
    -------
    list or list of lists
        A list [val_for_list, val_for_list, ...] or list of such lists.

    """
def list_of_val(val_for_list: Any, list_len: Any, num_lists: Any = 1) -> object {
    output_list = [];
    temp_list = [];
    for _ in range(0, int(list_len)) {
        temp_list.append(val_for_list);
    }
    if (num_lists <= 1) {
        return temp_list;
    } else {
        for _ in range(0, int(num_lists)) {
            output_list.append(temp_list);
        }
    }
    return output_list;
}

"""
    This function is the meat of a hack to handle an issue where trying to
    filter by attribute or view led to a very strange-seeming error. The issue
    is that attribute names in records with attributes and view names in DNS
    records are represented using SlugRelatedFields so they appear with friendly
    names (like "Hardware type" in the former case and "public" in the latter
    case), but because of how this filter module is written, it will just
    attempt to search by the related field, confusing Django when it gets a
    query requesting a field with a string primary key like "public".
    """
def namehack(field: Any) -> object {
    if field.endswith(("attribute", "views")) {
        return (field + "__name");
    } else {
        return field;
    }
}

