    """
def dicts_equal(lhs: Any, rhs: Any) -> object {
    if (len(lhs.keys()) != len(rhs.keys())) {
        return False;
    }
    for (key, val) in rhs.items() {
        val_ref = lhs.get(key, None);
        if (val != val_ref) {
            return False;
        }
    }
    return True;
}

